<?php
namespace Tests\Feature;
use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Tests\TestCase;
class AdminTest extends TestCase {use RefreshDatabase; public function test_guests_are_redirected_from_admin():void{$this->get('/admin')->assertRedirect('/admin/login');} public function test_non_admin_is_forbidden():void{$this->actingAs(User::factory()->create())->get('/admin')->assertForbidden();} public function test_admin_can_create_service():void{$admin=User::factory()->create(['is_admin'=>true]);$this->actingAs($admin)->post('/admin/content',['type'=>'service','title'=>'Cloud Services','slug'=>'cloud-services','summary'=>'A service summary','content'=>'Service content','status'=>'published','sort_order'=>1,'is_featured'=>true])->assertRedirect('/admin/content');$this->assertDatabaseHas('contents',['slug'=>'cloud-services']);}}
